{"success": true, "data": {"stdout": """"Batch lead-lag analysis for distributional canary collapse experiments.

Reads all_metrics.json from an experiment directory, runs 5-method lead-lag
analysis on all canary-diversity pairs, computes K>=4 consensus, and optionally
runs full MMCT if null directories are provided.

Usage:
    python batch_analysis.py --exp_dir results/alpha_sweep/a010_s43_bf16
    python batch_analysis.py --exp_dir results/alpha_sweep/a010_s43_bf16 \
        --null_dirs results/alpha_sweep/a000_s42 results/alpha_sweep/a000_s43

Input:  {exp_dir}/all_metrics.json
Output: {exp_dir}/analysis_results.json (or --output path)

Dependencies: numpy, scipy, statsmodels
"""

import argparse
import json
import os
import sys
import traceback
import numpy as np
from scipy import stats
from statsmodels.tsa.stattools import adfuller

N_PERM = 5000
ALPHA_SIG = 0.05

CANARIES = ["token_entropy", "ece"]
DOWNSTREAMS = ["distinct_1", "distinct_2", "distinct_3", "mauve"]

HIGHER_IS_WORSE = {"ece", "perplexity"}
LOWER_IS_WORSE = {"token_entropy", "distinct_1", "distinct_2", "distinct_3", "mauve"}

ALL_METRICS = ["token_entropy", "ece", "perplexity", "distinct_1", "distinct_2",
               "distinct_3", "effective_rank", "mauve"]


def load_series(data_dir):
    path = os.path.join(data_dir, "all_metrics.json")
    with open(path) as f:
        data = json.load(f)
    data.sort(key=lambda x: x["generation"])
    out = {}
    for k in ALL_METRICS:
        vals = []
        for d in data:
            v = d.get(k)
            vals.append(v if v is not None else np.nan)
        out[k] = np.array(vals, dtype=float)
    return out, len(data)


def orient(series, name):
    return -series.copy() if name in LOWER_IS_WORSE else series.copy()


def compute_drift(series_dict, n_gens):
    drift = {}
    for k in ALL_METRICS:
        s = series_dict.get(k)
        if s is None or len(s) < 2:
            drift[k] = None
            continue
        v0, v_last = s[0], s[-1]
        if abs(v0) < 1e-12:
            drift[k] = None
        else:
            drift[k] = round(float((v_last - v0) / abs(v0) * 100), 2)
    return drift


def bh_fdr(p_values, alpha=0.05):
    pv = np.array(p_values, dtype=float)
    n = len(pv)
    valid = ~np.isnan(pv)
    adjusted = np.full(n, np.nan)
    if valid.sum() == 0:
        return adjusted.tolist(), [False] * n
    idx = np.where(valid)[0]
    p_valid = pv[idx]
    sorted_idx = np.argsort(p_valid)
    ranks = np.empty_like(sorted_idx)
    ranks[sorted_idx] = np.arange(1, len(p_valid) + 1)
    m = len(p_valid)
    adj = p_valid * m / ranks
    adj_sorted = adj[sorted_idx].copy()
    for i in range(m - 2, -1, -1):
        adj_sorted[i] = min(adj_sorted[i], adj_sorted[i + 1])
    adj_sorted = np.minimum(adj_sorted, 1.0)
    adj_final = np.empty(m)
    adj_final[sorted_idx] = adj_sorted
    for i, ix in enumerate(idx):
        adjusted[ix] = adj_final[i]
    significant = [(adjusted[i] < alpha if not np.isnan(adjusted[i]) else False) for i in range(n)]
    return adjusted.tolist(), significant


# ── Method 1: Naive cross-correlation ──

def naive_xcorr(c, d, cn, dn, max_lag=5):
    x, y = orient(c, cn), orient(d, dn)
    n = len(x)
    if np.any(np.isnan(x)) or np.any(np.isnan(y)):
        return {"method": "naive_xcorr", "peak_lag": None, "r": None,
                "p_value": None, "significant": False, "note": "NaN in data"}
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-max_lag, max_lag + 1):
        if lag >= 0:
            a, b = x[lag:], y[:n - lag]
        else:
            a, b = x[:n + lag], y[-lag:]
        if len(a) < 4:
            continue
        if np.std(a) < 1e-12 or np.std(b) < 1e-12:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {
        "method": "naive_xcorr",
        "peak_lag": int(best_lag),
        "r": round(float(best_r), 4),
        "p_value": round(float(best_p), 6),
        "significant": bool(best_p < ALPHA_SIG),
    }


# ── Method 2: Differenced cross-correlation ──

def diff_xcorr(c, d, cn, dn, max_lag=5):
    x, y = orient(c, cn), orient(d, dn)
    if np.any(np.isnan(x)) or np.any(np.isnan(y)):
        return {"method": "diff_xcorr", "peak_lag": None, "r": None,
                "p_value": None, "significant": False, "note": "NaN in data"}
    dx, dy = np.diff(x), np.diff(y)
    n = len(dx)
    best_lag, best_r, best_p = 0, 0.0, 1.0
    for lag in range(-max_lag, max_lag + 1):
        if lag >= 0:
            a, b = dx[lag:], dy[:n - lag]
        else:
            a, b = dx[:n + lag], dy[-lag:]
        if len(a) < 4:
            continue
        if np.std(a) < 1e-12 or np.std(b) < 1e-12:
            continue
        r, p = stats.pearsonr(a, b)
        if abs(r) > abs(best_r):
            best_lag, best_r, best_p = lag, r, p
    return {
        "method": "diff_xcorr",
        "peak_lag": int(best_lag),
        "r": round(float(best_r), 4),
        "p_value": round(float(best_p), 6),
        "significant": bool(best_p < ALPHA_SIG),
    }


